async function handoffPrompt(host13, text, wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms))) {
  if (!host13.composer?.insertText) return "unavailable";
  const runtime = host13.state.focusedSessionId?.get();
  const stored = host13.state.focusedStoredSessionId?.get();
  const profile = host13.state.focusedSessionProfile?.get();
  const address = typeof stored === "string" && stored ? stored : typeof runtime === "string" && runtime ? runtime : null;
  if (await host13.composer.insertText(address, text, { mode: "block" })) return "inserted";
  if (typeof stored !== "string" || !stored || !host13.openSession) return "no-composer";
  await host13.openSession(stored, { intent: "in-place", ...typeof profile === "string" ? { profile } : {} });
  for (let attempt = 0; attempt < 10; attempt++) {
    await wait(150);
    if (await host13.composer.insertText(address, text, { mode: "block" })) return "inserted";
  }
  return "no-composer";
}

